outputs={}
for e in edits:
    path=e['file'];text=outputs.get(path,(ROOT/path).read_text(encoding='utf-8-sig'))
    old=json.dumps(e['before'],ensure_ascii=False);new=json.dumps(e['after'],ensure_ascii=False)
    if old not in text:raise SystemExit('Target not found: '+path+' / '+e['before'])
    outputs[path]=text.replace(old,new)
for path,text in outputs.items():(ROOT/path).write_text(text,encoding='utf-8')
(ROOT/'Documentation/Editorial/Decisions-Dialogue-v6.json').write_text(json.dumps(edits,ensure_ascii=False,indent=2),encoding='utf-8')
print(f'APPLIED / {len(edits)} reviewed dialogue/receipt edits / {len(outputs)} files')
